 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            minr = min(r for r, c in cells)
            maxr = max(r for r, c in cells)
            minc = min(c for r, c in cells)
            maxc = max(c for r, c in cells)
            occupied = set(cells)
            zeros = {(r, c) for r in range(minr, maxr + 1)
                     for c in range(minc, maxc + 1) if (r, c) not in occupied}
            exterior = set()
            flood = deque()
            for r, c in zeros:
                if r in (minr, maxr) or c in (minc, maxc):
                    exterior.add((r, c))
                    flood.append((r, c))
            while flood:
                r, c = flood.popleft()
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (r + dr, c + dc)
                    if p in zeros and p not in exterior:
                        exterior.add(p)
                        flood.append(p)
            hollow = bool(zeros - exterior)
            objects.append({"color": color, "cells": cells, "hollow": hollow,
                            "top": minr, "bottom": maxr})

    result = [[0] * w for _ in range(h)]
    for direction, group in ((-1, [o for o in objects if o["hollow"]]),
                             (1, [o for o in objects if not o["hollow"]])):
        # Settle nearer objects first, preserving their vertical order.
        group.sort(key=lambda o: o["top"] if direction < 0 else -o["bottom"])
        placed = set()
        for obj in group:
            cells = obj["cells"]
            shift = 0
            while True:
                next_shift = shift + direction
                candidate = {(r + next_shift, c) for r, c in cells}
                if any(r < 0 or r >= h for r, c in candidate) or candidate & placed:
                    break
                shift = next_shift
            moved = {(r + shift, c) for r, c in cells}
            placed.update(moved)
            for r, c in moved:
                result[r][c] = obj["color"]
    return result
